// TH14 合成弹型别名，见 transcribe/th14/bullet-types.md。
// 本卡源 type8=TH14_RICE、type18=TH14_BIG_BALL，色号沿用源 etSprite 的 2。
const TH14_RICE: int = 480;
const TH14_BIG_BALL: int = 640;

// TH14 v1.00b Stage 2 Boss 非符：st02bs.ecl.txt::Boss2 入口（原行 215-259）。
// 源卡帧关系：源入口从卡帧 120 开始执行；2280 帧源超时（:239）停止发射并清子敌，
// 相位计时 2764 帧把 360 帧尾弹窗口留在段内。后继 BossCard2 不启动。

const TIME_LIMIT: int = 2764;
const OPENING_BUFFER: int = 120;
const SRC_TIME_LIMIT: int = 2280;
// 跨任务停止位：源超时后 killAllAsync + enmKillAll 的静态替代（at3/at2/全部子敌返回）。
const GVAR_B2_STOP: int = 16;

// Boss2_at（:281-320）稻弹：EX WAIT 100 后 DELETE。出生阶段按批准口径省略，
// 剩余寿命 100 帧即 DELETE 时点；LAYER/BRIGHT 纯表现省略。
xformdef B2_RICE {
    set_life(100);
}

// Boss2_at2（:322-391）大玉：ANIM 出生省略后，
// VELTIME(a=60,r=0) -> WAIT(60/30/20) -> VELTIME(a=90,r=3/4/5)，方向保持。
xformdef B2_BIG(target: fx, pause: int) {
    step_speed(0fx, 60);
    wait(60 + pause);
    step_speed(target, 90);
}

// ---------- 外壳 ----------
async sub b2_pattern() {
    wait(OPENING_BUFFER);
    // Boss 公共入口 :15 movePos(0,128)，落地代表位置；:24-25 setHurtbox(40,40)/setHitbox(48,48)。
    _ = spawn_enemy(0fx, 128fx, 12900, 0, 0, 0, b2_boss);   // :219 lifeSet(12900)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, b2_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// ---------- Boss2 ----------
async sub b2_boss() {
    set_invuln(65535);                    // 训练外壳无DPS，覆盖源 :243 setInvuln(120)
    set_hitbox(24fx);                     // :25 setHitbox(48,48) 普通圆 -> 24
    set_hurtbox(20fx);                    // :24 setHurtbox(40,40) 普通圆 -> 20
    move_vel(0, 0deg, 0fx, EASE_LINEAR);  // :233 moveVel(0,0)
    move_to(0, $self_x, $self_y, EASE_LINEAR);   // :235 movePosTime(0,0,0,0)
    set_self_int(0, 60);                  // moveRand 步计数：首次 moveRand 前恒 0 速
    set_self_fx(0, 1fx);
    set_self_fx(1, 0fx);
    set_self_int(2, 4096);                // :248 %F0 = 0.392699 rad = 22.5deg
    set_global(GVAR_B2_STOP, 0);
    wait(60);                             // :245
    spawn b2_horn();                      // :249 @Boss2_at3() async
    spawn b2_fan();                       // :250 @Boss2_at2() async
    var t: int = 60;
    loop {
        wait(1);
        t = t + 1;
        if t >= SRC_TIME_LIMIT { break; } // :239 源超时 2280
        // :252-257 wait(60); moveRand(120,4,0.75); wait(120) -> t=120+180k
        if t % 180 == 120 { b2_move_rand(); } else { b2_arm_step(); }
    }
    set_global(GVAR_B2_STOP, 1);
}

// moveRand(120,4,0.75) 配方（transcribe/th16/movement.md），按本卡 moveLimit(0,128,280,64)
// 取实际边界 x[-140,140] y[96,160]，方向内区 x±70 y112..144。
sub b2_arm_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 120 { speed = (0.75fx * ((120 - k) as fx)) / 120fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub b2_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    b2_arm_step();
}

sub b2_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    b2_begin_angle(a as angle);
}

// Boss2_at3（:393-418）：每轮 16 个 Boss2At；%F0 每次 +0.392699 rad；间隔 16/8/6/5。
async sub b2_horn() {
    loop {
        if global(GVAR_B2_STOP) != 0 { return; }
        _ = spawn_enemy($self_x, $self_y, 10, 0, 0, 0, b2_head(self_int(2) as angle));
        set_self_int(2, self_int(2) + 4096);      // :402 %F0 = %F0 + 0.392699
        var w: int = 16;
        var rank: int = global(GVAR_RANK);
        if rank == 1 { w = 8; }
        if rank == 2 { w = 6; }
        if rank == 3 { w = 5; }
        wait(w);
    }
}

// Boss2At（:261-279）+ Boss2_at（:281-320）合并为同一子敌主任务：
// 出弹帧 f≡1 (mod 6)、转向重抽帧 f≡0 (mod 60)，从不重合，帧序不变。
async sub b2_head(dir: angle) {
    set_invuln(65535);                    // 训练外壳无DPS
    var a: angle = dir;
    var d: int = 0;
    var f: int = 0;
    var shots: int = 0;
    move_vel(0, a, 32fx, EASE_LINEAR);    // :265
    wait(1);                              // :266
    move_vel(0, a, 1fx, EASE_LINEAR);     // :267
    loop {
        wait(1);
        f = f + 1;
        if f >= 600 { return; }                     // :271-278 10 x wait(60) 后 delete
        if global(GVAR_B2_STOP) != 0 { return; }    // 源超时清子敌
        move_vel(0, a, 1fx, EASE_LINEAR);           // ABS 角状态，速度恒 1
        if f % 6 == 1 && shots < 700 {
            // :313 etAngle(%ABS_ANGLE); :289 etSpeed 0.01；ANIM 出生退位移 4v。
            _ = fire(TH14_RICE, 2, $self_x - 0.04fx * cos(a), $self_y - 0.04fx * sin(a),
                     0.01fx, a, B2_RICE, none);
            shots = shots + 1;
        }
        if f % 60 == 0 { d = (rand(65536) - 32768) / 450; }   // :273 %A = %RANDRAD/450
        a = a + (d as angle);                                // :274 moveAngleTime mode7
    }
}

// Boss2_at2（:322-391）：自机狙扇形大玉；E/N 1x1，H 1x3，L 5x5。
async sub b2_fan() {
    var n_ang: int = 1;
    var n_lay: int = 1;
    var pause: int = 60;
    var target: fx = 3fx;
    var rank: int = global(GVAR_RANK);
    if rank == 2 { n_lay = 3; pause = 30; target = 4fx; }
    if rank == 3 { n_ang = 5; n_lay = 5; pause = 20; target = 5fx; }
    wait(300);                            // :370
    var volleys: int = 700;               // :371
    loop {
        if global(GVAR_B2_STOP) != 0 { return; }
        var alpha: int = 0;
        if rank == 3 { alpha = (rand(65536) - 32768) / 60; }  // :375 %RANDRAD/_f(60)
        var aim: int = aim_player() as int;
        for q in 0..n_lay {               // :346 etSpeed(2,1) 端点 -> 逐层速
            var speed: fx = 2fx;
            if n_lay > 1 { speed = 2fx + (1fx - 2fx) * (q as fx) / ((n_lay - 1) as fx); }
            for i in 0..n_ang {           // :346 etAngle(alpha, 0.2618) mode0 扇形
                var off: int = ((i + 1) / 2) * 2731;
                if n_ang % 2 == 0 { off = (i / 2) * 2731 + 1365; }
                if i % 2 != 0 { off = -off; }
                var ang: angle = (aim + alpha + off) as angle;
                // ANIM 出生退位移 position -= 4*velocity（:348 首条 EX）。
                _ = fire(TH14_BIG_BALL, 2, $self_x - 4fx * speed * cos(ang),
                         $self_y - 4fx * speed * sin(ang), speed, ang, B2_BIG(target, pause), none);
            }
        }
        wait(30);                         // :387 E100/N100/H50/L30
        volleys = volleys - 1;
        if volleys == 0 { return; }       // :371 $B=700
    }
}
